// src/birth-moment.ts
import { DateTime } from "luxon";
var TzError = class extends Error {
  constructor(message) {
    super(message);
    this.name = "TzError";
  }
};
function resolveBirthMoment(input) {
  const { date, time, tz: tzName } = input;
  const warnings = [];
  if (!tzName) {
    throw new TzError("input.tz is required; pass an IANA zone resolved by the caller");
  }
  if (!DateTime.local().setZone(tzName).isValid) {
    throw new TzError(`unknown IANA zone: ${tzName}`);
  }
  const [y, m, d] = date.split("-").map(Number);
  const [hh, mm, ss = 0] = time.split(":").map(Number);
  if (y === void 0 || m === void 0 || d === void 0 || hh === void 0 || mm === void 0) {
    throw new TzError(`unparseable local datetime ${date}T${time}`);
  }
  const local = DateTime.fromObject(
    { year: y, month: m, day: d, hour: hh, minute: mm, second: ss },
    { zone: tzName }
  );
  if (!local.isValid) {
    throw new TzError(
      `unparseable local datetime ${date}T${time} in ${tzName}: ${local.invalidReason}`
    );
  }
  if (local.hour !== hh || local.minute !== mm) {
    warnings.push(
      `local time ${time} does not exist in ${tzName} on ${date} (daylight-saving gap); resolved to ${local.toFormat("HH:mm")}`
    );
  }
  const oneHourLater = DateTime.fromMillis(local.toMillis() + 36e5).setZone(tzName);
  if (oneHourLater.offset !== local.offset && oneHourLater.hour === local.hour && oneHourLater.minute === local.minute) {
    warnings.push(
      `local time ${time} occurred twice in ${tzName} on ${date} (daylight-saving fall-back); resolved to the first (daylight) occurrence`
    );
  }
  const utc = local.toUTC();
  return {
    tzName,
    utcDateTime: utc.toISO(),
    utcOffsetHours: local.offset / 60,
    // Julian Day (UT) from the Unix epoch, which is JD 2440587.5.
    julianDay: utc.toMillis() / 864e5 + 24405875e-1,
    warnings
  };
}

